const drums = stack(
  s("bd*4"),
  s("hh*8").gain("[0.25 0.45]*4"),
  s("[~ oh]*4").gain(0.35),
  s("~ cp ~ cp").gain(0.6),
  s("rim(3,8,2)").gain(0.3),
).bank("RolandTR909").swingBy(1/6, 4)
const bass = note("<[~ c2 ~ c2 ~ c2 ~ eb2] [~ c2 ~ c2 ~ g1 ~ bb1]>").s("sawtooth")
  .lpf(700).decay(0.15).sustain(0).gain(0.5)
const chords = chord("<Cm7 Cm7 Ab^7 Bb7>").voicing()
  .struct("~ x ~ ~ ~ x ~ ~").s("square")
  .lpf(1400).decay(0.25).sustain(0).room(0.4).gain(0.3)
const lead = chord("<Cm7 Cm7 Ab^7 Bb7>").voicing().arp("0 1 2 3 2 1 2 3")
  .add(note(12)).s("triangle").decay(0.15).sustain(0).gain(0.3)
const roll = s("sd*4").bank("RolandTR909").ply("<1 1 2 2 4 4 8 8>").gain(0.4)
arrange(
  [8, stack(drums, chords)],
  [8, stack(drums, bass, chords, roll)],
  [16, stack(drums, bass, chords, lead)],
  [8, stack(drums, chords.lpf(600))],
)
